: \"Exchange Stabilization Fund\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [198, 1468, 1382, 1519], \"page_id\": 9}], \"content\": \"International financial statistics 84\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [187, 1545, 1371, 1596], \"page_id\": 9}], \"content\": \"Capital movements 89\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [198, 1608, 1367, 1668], \"page_id\": 9}], \"content\": \"Corporations and other business-type activities 126\", \"description\": null, \"id\": 19, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [194, 1690, 1376, 1741], \"page_id\": 9}], \"content\": \"Cumulative table of contents 127\", \"description\": null, \"id\": 20, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [194, 1806, 1063, 1849], \"page_id\": 9}], \"content\": \"Note: Details of figures may not add to totals because of rounding.\", \"description\": null, \"id\": 21, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [71, 29, 96, 55], \"page_id\": 10}], \"content\": \"II\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [1323, 12, 1588, 58], \"page_id\": 10}], \"content\": \"Treasury Bulletin\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [604, 293, 1080, 324], \"page_id\": 10}], \"content\": \"Treasury Financing Operations\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [62, 406, 279, 430], \"page_id\": 10}], \"content\": \"October Refunding\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [62, 454, 809, 632], \"page_id\": 10}], \"content\": \"On September 17 the Treasury announced an exchange offering of 8% Treasury Notes of Series E-1971, dated October 1, 1969, due May 15, 1971, at par, 7-3/4% Treasury Notes of Series A-1973, dated October 1, 1969, due May 15, 1973, at par, and 7-1/2% Treasury Notes of Series C-1976, dated October 1, 1969,\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [880, 401, 1598, 540], \"page_id\": 10}], \"content\": \"due August 15, 1976, at 99.50 to yield about 7.99%, to hold of 1-1/2% Treasury Notes of Series EO-1969, due October 1 1969, 4% Treasury Bonds of 1969, due October 1, 1969, and 2-1/2% Treasury Bonds of 1964-69, due December 15, 1969.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [884, 564, 1598, 627], \"page_id\": 10}], \"content\": \"The following table contains figures relating to amount exchanged.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [657, 677, 1011, 704], \"page_id\": 10}], \"content\": \"(Dollar amounts in millions)\", \"description\": null, \"id\": 7, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [55, 704, 1600, 1146], \"page_id\": 10}], \"content\": \"<table><tr><th colspan=\\\"2\\\">ELIGIBLE FOR EXCHANGE</th><th colspan=\\\"4\\\">SECURITIES TO BE ISSUED</th><th colspan=\\\"2\\\">UNEXCHANGED</th></tr><tr><th>Securities</th><th>Amount</th><th>8% Notes E-1971</th><th>7-3/4% Notes A-1973</th><th>7-1/2% Notes C-1976</th><th>Total</th><th>Amount</th><th>Percent</th></tr><tr><td>1-1/2% notes</td><td>$ 159</td><td>$ 51</td><td>$ 13</td><td>$ 2</td><td>$ 66</td><td>$ 93</td><td>58.5</td></tr><tr><td>4% bonds</td><td>6,240</td><td>3,172</td><td>870</td><td>1,108</td><td>5,150</td><td>1,090</td><td>19.8</td></tr><tr><td>2-1/2% bonds</td><td>2,484</td><td>950</td><td>275</td><td>571</td><td>1,796</td><td>688</td><td>34.2</td></tr><tr><td>Total</td><td>$8,883</td><td>$4,173</td><td>$1,158</td><td>$1,681</td><td>$7,012</td><td>$1,871</td><td>24.3</td></tr></table>\", \"description\": null, \"id\": 8, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [68, 1172, 812, 1242], \"page_id\": 10}], \"content\": \"The subscription books were open from September 22 through September 24. Cash subscriptions were not accepted.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [127, 1256, 807, 1283], \"page_id\": 10}], \"content\": \"In the case of exchanges of the 2-1/2% bonds, coupons\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [873, 1172, 1596, 1271], \"page_id\": 10}], \"content\": \"dated December 15, 1969, were to be attached to the bonds and interest was to be adjusted as of that date, with payments as follows (per $1,000 face value):\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [64, 1304, 1600, 1662], \"page_id\": 10}], \"content\": \"<table><tr><th rowspan=\\\"2\\\">NEW NOTES</th><th colspan=\\\"2\\\">Payable to Subscriber</th><th colspan=\\\"2\\\">Accrued Interest Payable</th><th colspan=\\\"2\\\">Net Amount to be Paid</th></tr><tr><th>Account of Issue Price of New Notes</th><th>To Adjust for Market Value of Bonds</th><th>To Subscriber on Bonds (6/15/69 to 12/15/69)</th><th>By Subscriber on Notes (10/1/69 to 12/15/69)</th><th>To Subscriber</th><th>To Treasury</th></tr><tr><td>8% due 5/15/71</td><td>$ -</td><td>$ 2.70</td><td>$12.50</td><td>$16.41244</td><td>$ -</td><td>$1.21244</td></tr><tr><","annotations":{"priority":0.0}}],"structuredContent":{"stdout":"{\"document\": {\"elements\": [{\"bbox\": [{\"coord\": [-4, -2, 1663, 2206], \"page_id\": 1}], \"content\": null, \"description\": null, \"id\": 0, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [662, 841, 883, 891], \"page_id\": 3}], \"content\": \"LIER + Y\", \"description\": null, \"id\": 0, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [688, 889, 848, 937], \"page_id\": 3}], \"content\": \"Room 50\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [675, 944, 880, 1000], \"page_id\": 3}], \"content\": \"JIL 28 1970\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [590, 1028, 952, 1079], \"page_id\": 3}], \"content\": \"TREASURY DEPARTMENT\", \"description